{"file_text": "@page "/settings"
@using sv_3752b157349f46d1861528f0f26af717.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <!-- Left sidebar navigation -->
    <nav class="settings-sidebar">
        <h4 class="sidebar-title">Settings</h4>
        @foreach (var section in _sections)
        {
            <button class="sidebar-item @(section == _activeSection ? "active" : "")"
                    @onclick="() => SetActiveSection(section)">
                <span class="sidebar-icon">@GetSectionIcon(section)</span>
                @section
            </button>
        }
    </nav>

    <!-- Main content area -->
    <div class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        <!-- Toast notification -->
        @if (_showToast)
        {
            <div class="toast-notification @(_toastType)">
                <span>@_toastMessage</span>
                <button class="toast-close" @onclick="() => _showToast = false">&times;</button>
            </div>
        }
    </div>
</div>

<!-- Session revoke confirmation modal -->
@if (_showRevokeDialog)
{
    <div class="modal-backdrop" @onclick="CancelRevoke">
        <div class="modal-dialog" @onclick:stopPropagation="true">
            <h5>Revoke Session</h5>
            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke?.Device</strong>?
               This will sign out that device immediately.</p>
            <div class="modal-actions">
                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke Session</button>
            </div>
        </div>
    </div>
}

@* ───────────────────── Profile Section ───────────────────── *@
@{ RenderFragment RenderProfileSection() =>
    @<section class="settings-section">
        <h3>Profile</h3>
        <p class="section-description">Manage your personal information and public profile.</p>

        <div class="avatar-area">
            <img src="@_editProfile!.AvatarUrl" alt="Avatar" class="avatar-preview"
                 onerror="this.src='https://via.placeholder.com/96?text=?'" />
            <div class="avatar-info">
                <label class="form-label">Avatar URL</label>
                <input type="text" class="form-control" @bind="_editProfile.AvatarUrl" />
            </div>
        </div>

        <div class="form-group">
            <label class="form-label">Display Name</label>
            <input type="text" class="form-control" @bind="_editProfile.DisplayName" />
        </div>

        <div class="form-group">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="_editProfile.Email" />
        </div>

        <div class="form-group">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="4" @bind="_editProfile.Bio"></textarea>
        </div>

        <div class="button-row">
            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    </section>;
}

@* ───────────────────── Notifications Section ───────────────────── *@
@{ RenderFragment RenderNotificationsSection() =>
    @<section class="settings-section">
        <h3>Notifications</h3>
        <p class="section-description">Choose how and when you want to be notified.</p>

        <div class="toggle-group">
            <div class="toggle-row">
                <div>
                    <strong>Email Notifications</strong>
                    <p class="toggle-description">Receive notifications via email.</p>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_editNotifications!.EmailNotifications" />
                    <span class="slider"></span>
                </label>
            </div>
            <div class="toggle-row">
                <div>
                    <strong>Push Notifications</strong>
                    <p class="toggle-description">Receive push notifications on your devices.</p>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_editNotifications.PushNotifications" />
                    <span class="slider"></span>
                </label>
            </div>
            <div class="toggle-row">
                <div>
                    <strong>Weekly Digest</strong>
                    <p class="toggle-description">Get a summary of activity each week.</p>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_editNotifications.WeeklyDigest" />
                    <span class="slider"></span>
                </label>
            </div>
        </div>

        <h5 class="mt-4">Muted Channels</h5>
        <p class="section-description">Muted channels will not send you any notifications.</p>
        <div class="channel-list">
            @foreach (var channel in _allChannels)
            {
                var ch = channel;
                <label class="channel-item">
                    <input type="checkbox"
                           checked="@_editNotifications.MutedChannels.Contains(ch)"
                           @onchange="e => ToggleMutedChannel(ch, (bool)e.Value!)" />
                    <span>@ch</span>
                </label>
            }
        </div>

        <div class="button-row">
            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    </section>;
}

@* ───────────────────── Security Section ───────────────────── *@
@{ RenderFragment RenderSecuritySection() =>
    @<section class="settings-section">
        <h3>Security</h3>
        <p class="section-description">Manage your password, two-factor authentication, and active sessions.</p>

        <!-- Change Password -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>🔑 Change Password</span>
                <span class="chevron @(_passwordPanelOpen ? "open" : "")">▸</span>
            </button>
            @if (_passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="form-group">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="form-group">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>
                    @if (!string.IsNullOrEmpty(_passwordError))
                    {
                        <div class="alert alert-danger">@_passwordError</div>
                    }
                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    @if (_security?.LastPasswordChange is not null)
                    {
                        <small class="text-muted ms-3">
                            Last changed @FormatTimeAgo(_security.LastPasswordChange.Value)
                        </small>
                    }
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="toggle-row mt-4">
            <div>
                <strong>Two-Factor Authentication</strong>
                <p class="toggle-description">
                    Add an extra layer of security to your account.
                    <span class="status-badge @(_security!.TwoFactorEnabled ? "enabled" : "disabled")">
                        @(_security.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </p>
            </div>
            <label class="switch">
                <input type="checkbox" checked="@_security.TwoFactorEnabled" disabled />
                <span class="slider"></span>
            </label>
        </div>

        <!-- Active Sessions -->
        <h5 class="mt-4">Active Sessions</h5>
        <div class="sessions-table-wrapper">
            <table class="table sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _security.Sessions)
                    {
                        var isCurrentSession = session.Id == _security.Sessions.First().Id;
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrentSession)
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@FormatTimeAgo(session.LastActive)</td>
                            <td>
                                @if (!isCurrentSession)
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => RequestRevoke(session)">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    </section>;
}

@* ───────────────────── Appearance Section ───────────────────── *@
@{ RenderFragment RenderAppearanceSection() =>
    @<section class="settings-section">
        <h3>Appearance</h3>
        <p class="section-description">Customize how the application looks and feels.</p>

        <!-- Theme -->
        <div class="form-group">
            <label class="form-label fw-bold">Theme</label>
            <div class="radio-group">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    var t = theme;
                    <label class="radio-option @(_editAppearance!.Theme == t ? "selected" : "")">
                        <input type="radio" name="theme" value="@t"
                               checked="@(_editAppearance.Theme == t)"
                               @onchange="() => _editAppearance.Theme = t" />
                        @t
                    </label>
                }
            </div>
        </div>

        <!-- Font Size -->
        <div class="form-group">
            <label class="form-label fw-bold">Font Size</label>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    var s = size;
                    <label class="radio-option @(_editAppearance!.FontSize == s ? "selected" : "")">
                        <input type="radio" name="fontSize" value="@s"
                               checked="@(_editAppearance.FontSize == s)"
                               @onchange="() => _editAppearance.FontSize = s" />
                        @s
                    </label>
                }
            </div>
        </div>

        <!-- Language -->
        <div class="form-group">
            <label class="form-label fw-bold">Language</label>
            <select class="form-select" @bind="_editAppearance!.Language">
                <option value="English">English</option>
                <option value="Spanish">Spanish</option>
                <option value="French">French</option>
                <option value="German">German</option>
                <option value="Japanese">Japanese</option>
                <option value="Chinese">Chinese</option>
                <option value="Portuguese">Portuguese</option>
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="toggle-row">
            <div>
                <strong>Compact Mode</strong>
                <p class="toggle-description">Reduce spacing and padding for a denser layout.</p>
            </div>
            <label class="switch">
                <input type="checkbox" @bind="_editAppearance!.CompactMode" />
                <span class="slider"></span>
            </label>
        </div>

        <!-- Live Preview -->
        <h5 class="mt-4">Preview</h5>
        <div class="live-preview @GetPreviewClasses()">
            <div class="preview-header">
                <strong>Sample Card</strong>
            </div>
            <div class="preview-body">
                <p>This is a preview of your selected appearance settings.</p>
                <button class="preview-btn">Sample Button</button>
                <span class="preview-badge">Badge</span>
            </div>
            <div class="preview-footer">
                Language: @_editAppearance.Language · Compact: @(_editAppearance.CompactMode ? "On" : "Off")
            </div>
        </div>

        <div class="button-row">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>
    </section>;
}

@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";
    private bool _loading = true;

    // Toast
    private bool _showToast;
    private string _toastMessage = "";
    private string _toastType = "success";

    // Profile
    private UserProfile? _savedProfile;
    private ProfileEdit? _editProfile;

    // Notifications
    private NotificationPrefs? _savedNotifications;
    private NotificationEdit? _editNotifications;
    private readonly List<string> _allChannels =
        ["#general", "#random", "#off-topic", "#engineering", "#design", "#announcements"];

    // Security
    private SecuritySettings? _security;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private bool _showRevokeDialog;
    private ActiveSession? _sessionToRevoke;

    // Appearance
    private AppearanceSettings? _savedAppearance;
    private AppearanceEdit? _editAppearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        _savedProfile = profileTask.Result;
        _editProfile = ProfileEdit.From(_savedProfile);

        _savedNotifications = notifTask.Result;
        _editNotifications = NotificationEdit.From(_savedNotifications);

        _security = securityTask.Result;

        _savedAppearance = appearanceTask.Result;
        _editAppearance = AppearanceEdit.From(_savedAppearance);
    }

    private async Task SetActiveSection(string section)
    {
        _activeSection = section;
        _showToast = false;
        await Task.CompletedTask;
    }

    // ── Profile ──

    private async Task SaveProfile()
    {
        var profile = new UserProfile(
            _editProfile!.DisplayName,
            _editProfile.Email,
            _editProfile.AvatarUrl,
            _editProfile.Bio
        );
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        ShowToast("Profile saved successfully.", "success");
    }

    private void DiscardProfileChanges()
    {
        _editProfile = ProfileEdit.From(_savedProfile!);
        ShowToast("Changes discarded.", "info");
    }

    // ── Notifications ──

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted && !_editNotifications!.MutedChannels.Contains(channel))
            _editNotifications.MutedChannels.Add(channel);
        else if (!muted)
            _editNotifications!.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(
            _editNotifications!.EmailNotifications,
            _editNotifications.PushNotifications,
            _editNotifications.WeeklyDigest,
            new List<string>(_editNotifications.MutedChannels)
        );
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _savedNotifications = prefs;
        ShowToast("Notification preferences saved.", "success");
    }

    // ── Security ──

    private async Task UpdatePassword()
    {
        _passwordError = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New passwords do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _security = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        ShowToast("Password updated successfully.", "success");
    }

    private void RequestRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeDialog = true;
    }

    private void CancelRevoke()
    {
        _showRevokeDialog = false;
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _security = await SettingsService.GetSecuritySettingsAsync();
        }
        _showRevokeDialog = false;
        _sessionToRevoke = null;
        ShowToast("Session revoked.", "success");
    }

    // ── Appearance ──

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_editAppearance!.Theme.ToLowerInvariant() switch
        {
            "dark" => "preview-dark",
            "system" => "preview-system",
            _ => "preview-light"
        });
        classes.Add(_editAppearance.FontSize.ToLowerInvariant() switch
        {
            "small" => "preview-font-sm",
            "large" => "preview-font-lg",
            _ => "preview-font-md"
        });
        if (_editAppearance.CompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(
            _editAppearance!.Theme,
            _editAppearance.FontSize,
            _editAppearance.Language,
            _editAppearance.CompactMode
        );
        await SettingsService.SaveAppearanceAsync(settings);
        _savedAppearance = settings;
        ShowToast("Appearance settings saved.", "success");
    }

    // ── Helpers ──

    private void ShowToast(string message, string type)
    {
        _toastMessage = message;
        _toastType = type;
        _showToast = true;
    }

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    private static string FormatTimeAgo(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    // ── Mutable edit models (records are immutable) ──

    private class ProfileEdit
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";

        public static ProfileEdit From(UserProfile p) => new()
        {
            DisplayName = p.DisplayName,
            Email = p.Email,
            AvatarUrl = p.AvatarUrl,
            Bio = p.Bio
        };
    }

    private class NotificationEdit
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; } = [];

        public static NotificationEdit From(NotificationPrefs p) => new()
        {
            EmailNotifications = p.EmailNotifications,
            PushNotifications = p.PushNotifications,
            WeeklyDigest = p.WeeklyDigest,
            MutedChannels = new List<string>(p.MutedChannels)
        };
    }

    private class AppearanceEdit
    {
        public string Theme { get; set; } = "Light";
        public string FontSize { get; set; } = "Medium";
        public string Language { get; set; } = "English";
        public bool CompactMode { get; set; }

        public static AppearanceEdit From(AppearanceSettings s) => new()
        {
            Theme = s.Theme,
            FontSize = s.FontSize,
            Language = s.Language,
            CompactMode = s.CompactMode
        };
    }
}
