    gap: 0;
    background: #f8f9fa;
    border-radius: 8px;
    overflow: hidden;
    border: 1px solid #dee2e6;
}

/* ── Sidebar ── */
.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: #fff;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
    display: flex;
    flex-direction: column;
}

.sidebar-title {
    padding: 0 1.25rem 1rem;
    margin: 0;
    font-weight: 700;
    color: #212529;
    font-size: 1.1rem;
    border-bottom: 1px solid #eee;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    color: #495057;
    cursor: pointer;
    transition: all 0.15s ease;
}

.sidebar-item:hover {
    background: #f0f0f0;
    color: #212529;
}

.sidebar-item.active {
    background: #e7f1ff;
    color: #0d6efd;
    font-weight: 600;
    border-right: 3px solid #0d6efd;
}

.sidebar-icon {
    font-size: 1.1rem;
    width: 1.5rem;
    text-align: center;
}

/* ── Content ── */
.settings-content {
    flex: 1;
    padding: 2rem;
    position: relative;
    overflow-y: auto;
    background: #fff;
}

.settings-section h3 {
    margin: 0 0 0.25rem;
    font-weight: 700;
    font-size: 1.5rem;
    color: #212529;
}

.section-description {
    color: #6c757d;
    margin-bottom: 1.5rem;
    font-size: 0.9rem;
}

/* ── Loading ── */
.loading-spinner {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 200px;
}

/* ── Avatar ── */
.avatar-area {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.avatar-preview {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
    flex-shrink: 0;
}

.avatar-info {
    flex: 1;
}

/* ── Form ── */
.form-group {
    margin-bottom: 1.25rem;
}

.form-label {
    font-weight: 500;
    margin-bottom: 0.35rem;
    display: block;
    color: #495057;
    font-size: 0.9rem;
}

.button-row {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
    padding-top: 1.5rem;
    border-top: 1px solid #eee;
}

/* ── Toggle Switch ── */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0;
}

.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-row:last-child {
    border-bottom: none;
}

.toggle-description {
    margin: 0.2rem 0 0;
    font-size: 0.85rem;
    color: #6c757d;
}

.switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
    flex-shrink: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #ccc;
    transition: 0.2s;
    border-radius: 26px;
}

.slider::before {
    content: "";
    position: absolute;
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background-color: #fff;
    transition: 0.2s;
    border-radius: 50%;
}

.switch input:checked + .slider {
    background-color: #0d6efd;
}

.switch input:checked + .slider::before {
    transform: translateX(22px);
}

.switch input:disabled + .slider {
    opacity: 0.6;
    cursor: not-allowed;
}

/* ── Channels ── */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    background: #f8f9fa;
    border-radius: 6px;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    padding: 0.35rem 0.5rem;
    border-radius: 4px;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #e9ecef;
}

.channel-item input[type="checkbox"] {
    width: 16px;
    height: 16px;
    accent-color: #0d6efd;
}

/* ── Expandable Panel ── */
.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 1rem 1.25rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
    color: #212529;
    transition: background 0.15s;
}

.panel-header:hover {
    background: #e9ecef;
}

.chevron {
    transition: transform 0.2s;
    font-size: 1.1rem;
}

.chevron.open {
    transform: rotate(90deg);
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #dee2e6;
}

/* ── Status badges ── */
.status-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 10px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-left: 0.5rem;
}

.status-badge.enabled {
    background: #d1e7dd;
    color: #0f5132;
}

.status-badge.disabled {
    background: #f8d7da;
    color: #842029;
}

.current-badge {
    display: inline-block;
    background: #cfe2ff;
    color: #084298;
    padding: 0.1rem 0.45rem;
    border-radius: 8px;
    font-size: 0.7rem;
    font-weight: 600;
    margin-left: 0.5rem;
    vertical-align: middle;
}

/* ── Sessions Table ── */
.sessions-table-wrapper {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
}

.sessions-table {
    margin: 0;
    font-size: 0.9rem;
}

.sessions-table thead th {
    background: #f8f9fa;
    font-weight: 600;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: #6c757d;
    border-bottom: 2px solid #dee2e6;
}

/* ── Radio Group ── */
.radio-group {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.5rem 1rem;
    border: 2px solid #dee2e6;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.15s;
    font-size: 0.9rem;
}

.radio-option:hover {
    border-color: #adb5bd;
}

.radio-option.selected {
    border-color: #0d6efd;
    background: #e7f1ff;
    color: #0d6efd;
    font-weight: 500;
}

.radio-option input[type="radio"] {
    accent-color: #0d6efd;
}

/* ── Live Preview ── */
.live-preview {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    transition: all 0.2s;
}

.preview-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #dee2e6;
}

.preview-body {
    padding: 1rem;
}

.preview-body p {
    margin-bottom: 0.75rem;
}

.preview-footer {
    padding: 0.5rem 1rem;
    font-size: 0.8rem;
    border-top: 1px solid #dee2e6;
}

.preview-btn {
    padding: 0.35rem 1rem;
    border-radius: 6px;
    border: none;
    cursor: default;
    font-size: inherit;
    margin-right: 0.5rem;
}

.preview-badge {
    display: inline-block;
    padding: 0.2rem 0.6rem;
    border-radius: 10px;
    font-size: 0.8em;
    font-weight: 600;
}

/* Preview: Light */
.preview-light {
    background: #fff;
    color: #212529;
}

.preview-light .preview-header {
    background: #f8f9fa;
}

.preview-light .preview-footer {
    background: #f8f9fa;
    color: #6c757d;
}

.preview-light .preview-btn {
    background: #0d6efd;
    color: #fff;
}

.preview-light .preview-badge {
    background: #cfe2ff;
    color: #084298;
}

/* Preview: Dark */
.preview-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-dark .preview-header {
    background: #181825;
    border-color: #45475a;
}

.preview-dark .preview-footer {
    background: #181825;
    color: #a6adc8;
    border-color: #45475a;
}

.preview-dark .preview-body {
    border-color: #45475a;
}

.preview-dark .preview-btn {
    background: #89b4fa;
    color: #1e1e2e;
}

.preview-dark .preview-badge {
    background: #45475a;
    color: #cdd6f4;
}

/* Preview: System */
.preview-system {
    background: linear-gradient(135deg, #fff 50%, #1e1e2e 50%);
    color: #212529;
}

.preview-system .preview-header {
    background: rgba(248, 249, 250, 0.85);
}

.preview-system .preview-footer {
    background: rgba(248, 249, 250, 0.85);
    color: #6c757d;
}

.preview-system .preview-btn {
    background: #0d6efd;
    color: #fff;
}

.preview-system .preview-badge {
    background: #cfe2ff;
    color: #084298;
}

/* Preview: Font sizes */
.preview-font-sm {
    font-size: 0.8rem;
}

.preview-font-md {
    font-size: 1rem;
}

.preview-font-lg {
    font-size: 1.2rem;
}

/* Preview: Compact */
.preview-compact .preview-header {
    padding: 0.4rem 0.75rem;
}

.preview-compact .preview-body {
    padding: 0.5rem 0.75rem;
}

.preview-compact .preview-body p {
    margin-bottom: 0.35rem;
}

.preview-compact .preview-footer {
    padding: 0.3rem 0.75rem;
}

/* ── Toast ── */
.toast-notification {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    padding: 0.75rem 1.25rem;
    border-radius: 8px;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-size: 0.9rem;
    font-weight: 500;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
    z-index: 1100;
    animation: toast-slide-in 0.25s ease;
}

.toast-notification.success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-notification.info {
    background: #cff4fc;
    color: #055160;
    border: 1px solid #b6effb;
}

.toast-notification.error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.toast-close {
    background: none;
    border: none;
    font-size: 1.25rem;
    line-height: 1;
    cursor: pointer;
    color: inherit;
    opacity: 0.7;
}

.toast-close:hover {
    opacity: 1;
}

@keyframes toast-slide-in {
    from {
        transform: translateY(1rem);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

/* ── Modal ── */
.modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 1050;
    animation: fade-in 0.15s ease;
}

.modal-dialog {
    background: #fff;
    border-radius: 12px;
    padding: 1.5rem;
    max-width: 440px;
    width: 90%;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
}

.modal-dialog h5 {
    margin: 0 0 0.75rem;
    font-weight: 700;
}

.modal-dialog p {
    color: #495057;
    font-size: 0.95rem;
    margin-bottom: 1.25rem;
}

.modal-actions {
    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
}

@keyframes fade-in {
    from { opacity: 0; }
    to { opacity: 1; }
}

/* ── Responsive ── */
@media (max-width: 768px) {
    .settings-layout {
        flex-direction: column;
    }

    .settings-sidebar {
        width: 100%;
        min-width: unset;
        flex-direction: row;
        overflow-x: auto;
        padding: 0;
        border-right: none;
        border-bottom: 1px solid #dee2e6;
    }

    .sidebar-title {
        display: none;
    }

    .sidebar-item {
        white-space: nowrap;
        padding: 0.75rem 1rem;
        border-right: none;
    }

    .sidebar-item.active {
        border-right: none;
        border-bottom: 3px solid #0d6efd;
    }
}
